/// `parsePreferenceIncludeInlayParameterNameHints`
fn parse_preference_include_inlay_parameter_name_hints(
    value: &Value,
) -> IncludeInlayParameterNameHints {
    if let Some(value) = value.as_str() {
        match &*value.to_lowercase() {
            "none" => return IncludeInlayParameterNameHints::NONE,
            "literals" => return IncludeInlayParameterNameHints::LITERALS,
            "all" => return IncludeInlayParameterNameHints::ALL,
            _ => {}
        }
    }
    IncludeInlayParameterNameHints::NONE
}

/// `parsePreferenceIndentStyle` — Go accepts `int`/`float64` and coerces.
fn parse_preference_indent_style(value: &Value) -> IndentStyle {
    if let Some(value) = value.as_str() {
        match &*value.to_lowercase() {
            "none" => return IndentStyle::NONE,
            "block" => return IndentStyle::BLOCK,
            "smart" => return IndentStyle::SMART,
            _ => {}
        }
    }
    if let Some(v) = value_as_int(value) {
        return IndentStyle(v as i32);
    }
    IndentStyle::SMART
}

/// `parsePreferenceJsxAttributeCompletionStyle`
fn parse_preference_jsx_attribute_completion_style(
    value: &Value,
) -> JsxAttributeCompletionStyle {
    if let Some(value) = value.as_str() {
        match &*value.to_lowercase() {
            "auto" => return JsxAttributeCompletionStyle::AUTO,
            "braces" => return JsxAttributeCompletionStyle::BRACES,
            "none" => return JsxAttributeCompletionStyle::NONE_VALUE,
            _ => {}
        }
    }
    JsxAttributeCompletionStyle::AUTO
}

/// `parsePreferenceOrganizeImportsCaseFirst`
fn parse_preference_organize_imports_case_first(value: &Value) -> OrganizeImportsCaseFirst {
    if let Some(value) = value.as_str() {
        match &*value.to_lowercase() {
            "default" => return OrganizeImportsCaseFirst::DEFAULT,
            "lower" => return OrganizeImportsCaseFirst::LOWER,
            "upper" => return OrganizeImportsCaseFirst::UPPER,
            _ => {}
        }
    }
    OrganizeImportsCaseFirst::DEFAULT
}

/// `serializePreferenceOrganizeImportsCaseFirst`
fn serialize_preference_organize_imports_case_first(value: OrganizeImportsCaseFirst) -> &'static str {
    match value {
        OrganizeImportsCaseFirst::DEFAULT => "default",
        OrganizeImportsCaseFirst::LOWER => "lower",
        OrganizeImportsCaseFirst::UPPER => "upper",
        _ => "default",
    }
}

/// `parsePreferenceOrganizeImportsCollation`
fn parse_preference_organize_imports_collation(value: &Value) -> OrganizeImportsCollation {
    if let Some(value) = value.as_str() {
        match &*value.to_lowercase() {
            "ordinal" => return OrganizeImportsCollation::ORDINAL,
            "unicode" => return OrganizeImportsCollation::UNICODE,
            _ => {}
        }
    }
    OrganizeImportsCollation::ORDINAL
}

/// `serializePreferenceOrganizeImportsCollation`
#[allow(unreachable_patterns)]
fn serialize_preference_organize_imports_collation(
    value: OrganizeImportsCollation,
) -> &'static str {
    // Go's `default:` arm returns "ordinal"; the bool newtype makes it
    // unreachable here.
    match value {
        OrganizeImportsCollation::ORDINAL => "ordinal",
        OrganizeImportsCollation::UNICODE => "unicode",
        _ => "ordinal",
    }
}

/// `parsePreferenceOrganizeImportsSort`
fn parse_preference_organize_imports_sort(value: &Value) -> OrganizeImportsSort {
    if let Some(value) = value.as_str() {
        match &*value.to_lowercase() {
            "auto" => return OrganizeImportsSort::AUTO,
            "ordinal" => return OrganizeImportsSort::ORDINAL,
            "ordinalignorecase" => return OrganizeImportsSort::ORDINAL_IGNORE_CASE,
            "natural" => return OrganizeImportsSort::NATURAL,
            "naturalignorecase" => return OrganizeImportsSort::NATURAL_IGNORE_CASE,
            _ => {}
        }
    }
    OrganizeImportsSort::AUTO
}

/// `serializePreferenceOrganizeImportsSort`
fn serialize_preference_organize_imports_sort(value: OrganizeImportsSort) -> &'static str {
    match value {
        OrganizeImportsSort::AUTO => "auto",
        OrganizeImportsSort::ORDINAL => "ordinal",
        OrganizeImportsSort::ORDINAL_IGNORE_CASE => "ordinalIgnoreCase",
        OrganizeImportsSort::NATURAL => "natural",
        OrganizeImportsSort::NATURAL_IGNORE_CASE => "naturalIgnoreCase",
        _ => "auto",
    }
}

