/// `impl serde::Serialize` — Go's `json.Marshal` calls `MarshalJSONTo`.
impl serde::Serialize for UserPreferences {
    fn serialize<S: serde::Serializer>(&self, serializer: S) -> Result<S::Ok, S::Error> {
        tsc_json::serialize_marshaler_to(self, serializer)
    }
}

/// `impl serde::Deserialize` — Go's `json.Unmarshal` calls `UnmarshalJSONFrom`
/// (defined in userpreferences.rs on the `UnmarshalerFrom` impl).
impl<'de> Deserialize<'de> for UserPreferences {
    fn deserialize<D: serde::Deserializer<'de>>(deserializer: D) -> Result<Self, D::Error> {
        tsc_json::deserialize_unmarshaler_from(deserializer)
    }
}
